cd /tmp
cat > scan.py <<'PY'
import concurrent.futures as cf, urllib.request, sys
base="http://127.0.0.1:55608/wp-content/plugins/"
slugs=[l.strip() for l in open("slugs.txt") if l.strip()]
def check(s):
    for suf in ("/","/readme.txt"):
        try:
            r=urllib.request.urlopen(base+s+suf,timeout=5)
            return (r.status,s+suf)
        except urllib.error.HTTPError as e:
            if e.code!=404:
                return (e.code,s+suf)
        except Exception:
            pass
    return None
hits=[]
with cf.ThreadPoolExecutor(max_workers=100) as ex:
    for res in ex.map(check,slugs):
        if res: hits.append(res); print(res, flush=True)
print("TOTAL HITS", len(hits))
PY
